let isWriting = false;
let pendingWrite = false;

function saveTodos() {
  if (isWriting) {
    pendingWrite = true;
    return;
  }

  isWriting = true;
  pendingWrite = false;

  const data = JSON.stringify(Array.from(todosMap.values()));
  fs.writeFile(DATA_FILE, data, "utf8", (error) => {
    isWriting = false;
    if (error) {
      console.error("Error saving todos to file:", error);
    }
    if (pendingWrite) {
      saveTodos();
    }
  });
}

